function renderSharedPayment(r){const host=sharedHost('Оплата');sharedBackRecord=true;const form=node('form','payment-card'),amount=sharedField('Сумма, ₽','number',r.summary.due||''),date=sharedField('Дата оплаты','date',sharedDate());form.append(amount.wrap,date.wrap);const b=sharedButton('Добавить',null,'primary');b.type='submit';form.append(b);form.onsubmit=e=>{e.preventDefault();sharedEvent(r,'payment',{amount:Number(amount.input.value),date:date.input.value})};host.append(form)}
async function requestSpecialist(){if(!tg?.initData){showToast('Приглашения доступны в Telegram');return}await closeSetup(true);if(!$('setup').hidden)return;const d=await sharedMutation('invite',{role:'client'});if(d)showSharedLink(d.link,d.record)}
function openSharedInvite(){if(!tg?.initData){showToast('Приглашения доступны в Telegram');return}sharedCurrent=null;renderSharedOffer(sharedHost('Пригласить клиента'))}
async function acceptSharedInvite(){if(!sharedInviteToken)return;const toClient=sharedInvitePreview?.role==='client',first=!services.some(s=>!isProvider(s))&&!sharedRecords.some(r=>r.client?.id===sharedUser?.id);const d=await sharedMutation('accept',{token:sharedInviteToken,confirmTerms:toClient,expectedVersion:sharedInvitePreview?.version});if(!d)return;sharedInviteToken='';sharedUncertain=false;sharedCurrent=d.record.id;if(!toClient){openSharedProfile(d.record);return}closeScreen('clientProfile',true);await selectWorkspace('personal');renderShared();const row=[...$('sharedServices').children].find(x=>x.dataset.recordId===d.record.id),face=row?.querySelector('button');if(face&&typeof face.animate==='function'&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)face.animate([{transform:'translateY(0)'},{transform:'translateY(-6px)'},{transform:'translateY(0)'}],{duration:500,easing:'ease-out'});if(first){askConfirm('Его сделала девушка, которая вечно забывала, сколько денег нужно на спорт и красоту, и когда заканчивается абонемент в зал 🙈\nТеперь всё в одном месте: записи, остатки и расходы 📅💸\nБесплатно для всех ✨ Работает через VPN 🛡️',{title:'👋 Это Сервисник',accept:'Понятно',cancel:false}).then(()=>hintSharedCard(d.record.id));return}sharedAddedPopup(sharedRecords.find(x=>x.id===d.record.id)||d.record)}
async function startShared(){if(!tg?.initData||typeof fetch!=='function'||!tg?.initDataUnsafe?.user)return;try{await refreshShared();$('sharedStatus').hidden=true;scheduleSharedPoll();const search=new URLSearchParams(window.location.search),param=new URLSearchParams(tg.initData).get('start_param')||search.get('invite'),recordId=search.get('record')||(param?.startsWith('r_')?param.slice(2):null);if(recordId){const record=sharedRecords.find(x=>x.id===recordId);if(record)openSharedProfile(record);else showToast('Запись недоступна',false,'error');return}if(param&&/^[a-f0-9]{48}$/.test(param)){sharedInviteToken=param;sharedCurrent=null;await previewSharedInvite();return}await restoreShareResume()}catch(e){$('sharedStatus').hidden=false;$('sharedStatus').textContent=e.message;$('sharedStatus').onclick=()=>startShared()}}
$('inviteClient').onclick=openSharedInvite;
function renderIncomeMonths(){const select=$('workIncomeMonth'),current=sharedDate().slice(0,7),selected=select.value||current,months=new Set([current,selected]);for(let i=-12;i<=12;i++){const d=new Date(current+'-01T12:00:00');d.setMonth(d.getMonth()+i);months.add(localDay(d).slice(0,7))}for(const r of sharedRecords)for(const e of r.events||[])if(e.kind==='payment'&&e.status==='confirmed')months.add(e.date.slice(0,7));select.replaceChildren();for(const value of [...months].sort().reverse()){const option=document.createElement('option');option.value=value;option.textContent=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(value+'-01T12:00:00')).replace(/\s*г\.$/,'');select.append(option)}select.value=selected;}
renderIncomeMonths();$('workIncomeMonth').onchange=()=>{renderShared();if(!$('incomePeriodHost').hidden)openIncomeDetails()};
window.addEventListener('online',()=>{if(sharedReady)refreshShared().catch(()=>{})});document.addEventListener('visibilitychange',()=>{if(sharedReady&&!document.hidden&&!sharedBusy)refreshShared(sharedCurrent&&!$('clientProfile').hidden&&!sharedBackRecord&&!sharedEditing?sharedCurrent:null).catch(()=>{})});

function scheduleSharedPoll(){if(sharedPoll||!sharedReady||typeof document.visibilityState==='undefined')return;sharedPoll=setTimeout(async()=>{sharedPoll=null;if(!document.hidden&&!sharedBusy)try{await refreshShared(sharedCurrent&&!$('clientProfile').hidden&&!sharedBackRecord&&!sharedEditing?sharedCurrent:null)}catch{}scheduleSharedPoll()},10000)}

function sharedPlanData(start,end){if(!sharedReady)return [];const key=localDay(start);return sharedRecords.filter(r=>r.client?.id===sharedUser.id&&r.state==='active').map(r=>{const enabled=!r.closed&&cloudMeta.sharedPlan?.[r.id]?.[key]!==false,future=enabled?sharedFutureCost(r,start,end):0;return {r,enabled,due:future,planned:future,debt:r.summary.due,prepaid:enabled?r.summary.prepaid:0,key}})}
function sharedPaid(start,end){let n=0;for(const r of sharedRecords)if(r.client?.id===sharedUser?.id)for(const e of r.events||[]){const d=e.kind==='payment'&&e.status==='confirmed'&&dateOnly(e.date.slice(0,10));if(d&&d>=start&&d<end)n+=e.amount}return n}
function sharedHomeTotals(){const range=budgetRange(),rows=sharedPlanData(range.start,range.end);return {due:rows.reduce((a,x)=>a+x.due,0),prepaid:rows.reduce((a,x)=>a+x.prepaid,0),paid:sharedPaid(range.start,range.end)}}
function renderSharedPlan(){if(!sharedReady)return;const ranges=planRanges(),start=ranges[0].start,end=ranges.at(-1).end,rows=sharedPlanData(start,end),base=services.filter(s=>!isProvider(s)),privateRows=base.map(planServiceData),privateDebt=base.reduce((n,s)=>n+outstandingVisits(s).reduce((v,x)=>v+x.amount,0),0),privateDue=privateRows.reduce((n,x)=>n+x.due,0);
 $('planPaid').textContent=money(base.reduce((n,s)=>n+paidBetween(s,start,end),0)+sharedPaid(start,end));$('planPrepaid').textContent=money(homePrepaidValue(base)+rows.reduce((a,x)=>a+x.prepaid,0));$('planDue').textContent=money(privateDue+rows.reduce((a,x)=>a+x.due,0));$('planDue').setAttribute('aria-label',$('planDue').textContent);const debt=privateDebt+rows.reduce((a,x)=>a+x.debt,0);$('planDebt').hidden=!debt;$('planDebt').textContent=debt?'Долг за посещения: '+money(debt):'';$('sharedPlanRows').replaceChildren();
 const chart=$('sharedPlanChart');chart.replaceChildren();for(const x of rows){const row=node('section','plan-row'),head=node('div','plan-row-head'),open=sharedButton(x.r.terms.name,()=>openSharedProfile(x.r),'plan-row-open'),toggle=node('button','plan-switch');toggle.type='button';toggle.setAttribute('role','switch');toggle.setAttribute('aria-label',x.r.terms.name+' в плане');toggle.setAttribute('aria-checked',String(x.enabled));toggle.append(node('i',''));toggle.onclick=async()=>{if(sharedBusy||cloudBusy)return;await setSharedPlan(x.r,!x.enabled);renderExpenseTotals();renderBudgetPlan()};open.classList.add('person-identity');if(x.r.provider)open.prepend(sharedAvatar(x.r.provider));head.append(open,toggle);row.append(head,node('span','small',x.enabled?'Предоплачено '+money(x.prepaid)+' · Запланировано '+money(x.due):x.r.summary.due?'Долг '+money(x.r.summary.due):'Не в плане'));$('sharedPlanRows').append(row);if(x.enabled){const lane=node('div','plan-lane'),label=node('div','plan-lane-label');label.append(node('strong','',x.r.terms.name),node('span','',x.r.summary.until?'до '+formatDate(dateOnly(x.r.summary.until)):'Осталось '+x.r.summary.remaining));const track=node('div','plan-track'),span=end-start,until=x.r.summary.until?dateOnly(x.r.summary.until):null,date=(cloudMeta.sharedPlan?.[x.r.id]?.schedule||x.r.terms.date)?dateOnly((cloudMeta.sharedPlan?.[x.r.id]?.schedule||x.r.terms.date).slice(0,10)):null;if(until&&x.prepaid>0){const bar=node('div','plan-segment');bar.style.left='0%';bar.style.width=(Math.max(0,Math.min(1,(until-start)/span))*100)+'%';track.append(bar)}if(x.planned>0)for(const at of occurrences(sharedScheduleService(x.r),start,end)){const day=dateOnly(localDay(at)),after=new Date(day);after.setDate(after.getDate()+1);if(!sharedFutureCost(x.r,day,after))continue;const marker=node('div','plan-segment future');marker.style.left=((at-start)/span*100)+'%';marker.style.width='4px';track.append(marker)}lane.append(label,track);chart.append(lane)}}
 if(rows.some(x=>x.enabled)){$('planChart').querySelector('.plan-empty')?.remove();$('planAxis').hidden=false}
}

function sharedProfileBack(force=false){if(sharedBusy)return false;if(!force&&sharedScheduleEdit?.isDirty()){showLeave('sharedSchedule');return false}if(force)sharedScheduleEdit=null;if(!force&&sharedBackRecord){const record=sharedRecords.find(r=>r.id===sharedCurrent);if(record){openSharedProfile(record);return false}}sharedScheduleEdit=null;return true}

function sharedFutureCost(r,start,end){
 if(r.closed||r.state!=='active')return 0;const service=sharedScheduleService(r),today=dateOnly(sharedDate()),from=new Date(Math.max(+today,+start)),future=occurrences(service,today,end).filter(d=>!occurrenceHasTime(service,d)||d>=new Date()),within=future.filter(d=>d>=from);if(!within.length)return 0;const t=r.terms,price=t.amount;
 if(t.paymentType==='visit')return price===null?0:Math.max(0,within.length*price-Math.max(0,(r.summary.prepaid||0)-future.filter(d=>d<from).length*price));
 const purchases=(r.events||[]).filter(e=>e.kind==='purchase'&&e.status!=='rejected');if(!purchases.length){const next=future[0];return next>=from&&price!==null?price:0}
 if(t.paymentType==='period')return 0;
 const credits=Math.max(0,(r.summary.remaining||0)-future.filter(d=>d<from).length),uncovered=Math.max(0,within.length-credits);return Number.isFinite(t.singlePrice)?uncovered*t.singlePrice:0
}
function incomeTotals(month){let paid=0,prepaid=0,due=0;const [year,m]=String(month).split('-').map(Number);if(!year||m<1||m>12)return {paid,prepaid,due};const start=cycleBoundary(year,m-1,budgetDay),end=cycleBoundary(year,m,budgetDay);for(const r of sharedRecords.filter(x=>x.provider?.id===sharedUser?.id)){paid+=(r.events||[]).filter(e=>e.kind==='payment'&&e.status==='confirmed'&&dateOnly(e.date)>=start&&dateOnly(e.date)<end).reduce((n,e)=>n+e.amount,0);prepaid+=r.summary.prepaid||0;due+=sharedFutureCost(r,start,end)}return {paid,prepaid,due}}

function openIncomeDetails(){sharedCurrent=null;const host=sharedHost('План доходов');$('incomePeriodHost').hidden=false;const records=sharedRecords.filter(r=>r.provider?.id===sharedUser?.id),{paid,prepaid,due}=incomeTotals($('workIncomeMonth').value);const totals=node('section','plan-widget'),amounts=node('div','plan-amounts');for(const [label,value] of [['Получено',paid],['Предоплачено',prepaid],['Запланировано',due]]){const cell=node('div','');cell.append(node('span','',label),node('strong','',money(value)));amounts.append(cell)}totals.append(amounts);const month=$('workIncomeMonth');const [year,m]=month.value.split('-').map(Number);$('incomeRange').textContent=formatDate(cycleBoundary(year,m-1,budgetDay))+' — '+formatDate(new Date(cycleBoundary(year,m,budgetDay)-86400000));host.append(totals);for(const r of records)host.append(sharedRow(r,true))}
const incomeWidget=$('workView').querySelector('.income');incomeWidget.onclick=()=>showSoon();incomeWidget.onkeydown=e=>{if(e.target===incomeWidget&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showSoon()}};

