async function previewSharedInvite(){const data=await sharedAPI('preview',{token:sharedInviteToken});if(data.record){sharedInviteToken='';openSharedProfile(data.record);return}sharedInvitePreview=data.invitation;if(data.invitation.role!=='client'){await acceptSharedInvite();return}const invite=data.invitation,toClient=invite.role==='client',host=sharedHost('Приглашение'),card=node('section','invite-from'),name=invite.from.name||'Специалист',avatar=sharedAvatar(invite.from),who=node('div','');who.append(node('strong','',name),node('span','small',toClient?'приглашает тебя':'хочет подключиться к тебе'));card.append(avatar,who);host.append(card);for(const t of invite.services||[invite.terms].filter(Boolean)){const termsCard=node('section','payment-card invite-offer'),price=t.amount===null?'без цены':money(t.amount);termsCard.append(node('h3','',t.name),node('p','',t.paymentType==='package'?t.count+' '+lessonWord(t.count)+' за '+price:t.paymentType==='period'?'Абонемент на '+t.duration+' мес. за '+price:'Разово · '+price));host.append(termsCard)}host.append(sharedButton(toClient?'Добавить к себе':'Принять клиента',acceptSharedInvite,'primary'));if(toClient)host.append(node('p','small invite-privacy','Платишь как обычно, напрямую 👌'))}

let invitationShareBusy=false;
function shareResumeKey(){return 'servisnik_share_'+sharedUser?.id}
function saveShareResume(value){try{if(value)localStorage.setItem(shareResumeKey(),JSON.stringify({...value,at:Date.now()}));else localStorage.removeItem(shareResumeKey())}catch{}}
async function returnFromShare(toClient){sharedCurrent=null;sharedEditing=false;sharedBackRecord=false;closeScreen('clientProfile',true);await selectWorkspace(toClient?'work':'personal');if(toClient)selectWorkSection('clients');renderShared()}
async function restoreShareResume(){let saved;try{saved=JSON.parse(localStorage.getItem(shareResumeKey()));localStorage.removeItem(shareResumeKey())}catch{return}if(!saved||Date.now()-saved.at>1800000)return;if(saved.sent){await returnFromShare(saved.toClient);return}const record=sharedRecords.find(r=>r.id===saved.id);if(!record||record.closed||record.state==='active')return;await selectWorkspace(saved.toClient?'work':'personal');showSharedLink(saved.url,record)}
async function shareInvitation(url,record,button){if(invitationShareBusy)return;invitationShareBusy=true;button.disabled=true;button.setAttribute('aria-busy','true');const resume={url,id:record?.id,toClient:!!record?.provider};const finish=()=>{invitationShareBusy=false;button.disabled=false;button.setAttribute('aria-busy','false')};const fallback=async()=>{saveShareResume(null);finish();try{await navigator.clipboard.writeText(url);showToast('Ссылка скопирована 📋 Вставь её в чат')}catch{showToast('Не получилось отправить 🙈 Обнови Telegram и попробуй ещё раз',false,'error')}};try{if(typeof tg.shareMessage!=='function'||!tg.isVersionAtLeast?.('8.0')){await fallback();return}const d=await sharedAPI('prepare-share',{token:new URL(url).searchParams.get('start')});saveShareResume(resume);tg.shareMessage(d.preparedMessageId,async sent=>{finish();if(sent){saveShareResume({...resume,sent:true});await returnFromShare(resume.toClient);showToast('Приглашение отправлено')}else{saveShareResume(null);showToast('Приглашение не отправлено')}})}catch{await fallback()}}

// A native single-person chooser; never enumerate contacts or create a shared relationship.
function canPickTelegramContact(){return !!tg?.initData&&typeof tg.requestChat==='function'&&tg.isVersionAtLeast?.('9.6')}
async function contactPickAPI(path,method='GET'){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);
 try{const r=await fetch('/api/contacts/'+path,{method,headers:{'X-Telegram-Init-Data':tg?.initData||''},signal:controller.signal}),d=await r.json();if(!r.ok)throw new Error(d.error);return d}finally{clearTimeout(timer)}
}
function contactPickerButton(onPicked){
 const button=node('button','secondary contact-picker','Выбрать в Telegram');button.type='button';button.hidden=!canPickTelegramContact();
 button.onclick=()=>pickTelegramContact(button,onPicked);return button;
}
async function pickTelegramContact(button,onPicked){
 if(button.disabled||!canPickTelegramContact())return;button.disabled=true;button.setAttribute('aria-busy','true');let done=false,timer;
 const finish=()=>{if(done)return false;done=true;clearTimeout(timer);button.disabled=false;button.setAttribute('aria-busy','false');return true};
 try{const prepared=await contactPickAPI('prepare','POST');
 timer=setTimeout(()=>{if(finish())showToast('Выбор не завершён. Можно повторить.')},90000);
 tg.requestChat(prepared.buttonId,async selected=>{
  if(done)return;if(!selected){finish();return}
  try{for(let i=0;i<30&&!done;i++){const result=await contactPickAPI('result?requestId='+prepared.requestId);if(done)return;if(result.contact){if(finish())onPicked(result.contact);return}await new Promise(resolve=>setTimeout(resolve,400))}if(finish())showToast('Контакт пока не получен. Повтори выбор.')}
  catch{if(finish())showToast('Не удалось получить контакт. Введи вручную.',false,'error')}
 });
 }catch{if(finish())showToast('Выбор недоступен. Введи @username вручную.',false,'error')}
}
function applySetupContact(w,person){if(setupState!==w||$('setup').hidden||w.step!==1)return;if(!w.providerName.trim())w.providerName=person.name;w.contact=person.username?'@'+person.username:'';w.channel=person.username?'Telegram':'';renderSetupFields();setupChanged();if(!person.username)showToast('У контакта нет @username. Введи телефон или ссылку.')}
